SUMMARIES = {
    "2606.00290": {"tldr": "Systematically determines the inducibility constants of all 6-vertex graphs using flag algebras, solving 30 new cases and establishing perfect stability in 32 cases.", "motivation": "The inducibility problem asks for the maximum asymptotic density of induced copies of a fixed graph F. While small graphs (up to 5 vertices) are well understood, the 78 cases for 6-vertex graphs represent the next frontier.", "method": "Flag algebra computations using semidefinite programming; stability analysis of extremal constructions; case analysis across 78 isomorphism classes up to complementation.", "result": "Sharp upper bounds on inducibility for 36 of 78 cases (30 new). Perfect stability established in 32 cases. Structural characterization of near-extremal graphs.", "conclusion": "Flag algebras are extremely effective for inducibility problems on small graphs. The 6-vertex case is largely resolved, with stability describing the structure of extremal graphs.", "future_work": "Remaining 42 open cases for 6-vertex graphs; extension to 7-vertex graphs using more powerful computational methods."},
    "2606.00691": {"tldr": "Solves the sharp A_alpha-spectral condition for existence of odd [1,b]-factors in graphs of even order, for alpha > 1/2.", "motivation": "Spectral extremal graph theory seeks degree-based or eigenvalue-based sufficient conditions for structural graph properties. Chen et al. reduced the odd [1,b]-factor problem to comparing spectral radii of obstruction graphs but left the comparison unresolved.", "method": "Spectral radius comparison among a family of obstruction graphs G_s = K_s \\nabla (K_{n-(b+1)s-1} \\cup (bs+1)K_1); algebraic and analytic bounds on the A_alpha-spectral radius.", "result": "Identifies the unique graph with maximal A_alpha-spectral radius among obstruction graphs, yielding a sharp spectral condition for odd [1,b]-factors when alpha > 1/2 and n is sufficiently large and even.", "conclusion": "The A_alpha-spectral approach successfully characterizes odd [1,b]-factors, unifying and extending previous results for specific values of b and alpha.", "future_work": "The case alpha <= 1/2 remains open; extension to [a,b]-factors with a > 1."},
    "2606.00976": {"tldr": "Determines exact rainbow Turan numbers for t-fans and even wheel graphs, extending the Keevash-Mubayi-Sudakov-Verstraete framework.", "motivation": "Rainbow Turan numbers ex*(n,H) forbid rainbow copies of H in properly edge-colored graphs. Exact values are known for few graphs beyond complete graphs. Fans and wheels are natural next candidates after edges and triangles.", "method": "Stability analysis of extremal constructions; structural characterization of rainbow-H-free colorings; matching upper and lower bounds via explicit constructions.", "result": "Exact values of ex*(n, F_t) for t-fans and ex*(n, W_{2k}) for even wheels determined for all sufficiently large n.", "conclusion": "The rainbow Turan problem for fans and even wheels exhibits a clean extremal structure, with the extremal constructions being natural generalizations of the Turan graph.", "future_work": "Odd wheel graphs; other rainbow-Turan extremal problems for graphs with more complex structure."},
    "2606.01996": {"tldr": "Proves new upper bounds on threshold Ramsey multiplicities of even cycles and odd paths, showing they are subpolynomial in the path/cycle length.", "motivation": "Threshold Ramsey multiplicity m(H) is the minimum number of monochromatic copies of H in any coloring of K_{r(H)}. Understanding this for paths and cycles is a central problem bridging Ramsey theory and counting.", "method": "Combinatorial counting arguments combined with local random constructions (random coloring with structured modifications) to bound the number of monochromatic copies.", "result": "m(C_{2t}) <= t^{-gamma+o(1)} (2t-1)!/2 and m(P_{2t+1}) <= t^{-gamma+o(1)} t/2 for some gamma > 0. The threshold Ramsey multiplicities decay faster than any polynomial.", "conclusion": "Even cycles and odd paths have surprisingly few forced monochromatic copies at the Ramsey threshold — far fewer than the total number of copies in the complete graph.", "future_work": "Determine the optimal gamma; extend to odd cycles and even paths; connections to the Kohayakawa-Kreuter conjecture."},
    "2606.02030": {"tldr": "Introduces DOM-bounded graph classes as a domatic analogue of chi-bounded classes, and connects this to the Gyarfas-Sumner conjecture.", "motivation": "Chi-boundedness (bounding chromatic number by clique number) is a central concept. The domatic number — maximum partition into dominating sets — satisfies dom(G) <= delta(G)+1, suggesting a parallel theory of DOM-bounded classes.", "method": "Structural graph theory; construction of graph classes with bounded domatic number relative to minimum degree; connections to forbidden induced subgraph theory.", "result": "Formal definition and basic properties of DOM-bounded classes. Counterparts to classical chi-boundedness results in the domatic setting. Relationship to the Gyarfas-Sumner conjecture on chi-boundedness.", "conclusion": "The domatic analogue of chi-boundedness is a rich framework that parallels classical results while revealing new structural phenomena.", "future_work": "Full characterization of DOM-bounded classes by forbidden induced subgraphs; domatic version of the Strong Perfect Graph Theorem."},
    "2606.02135": {"tldr": "Establishes systematic connections between hypergraph Turan problems and classical extremal set theory (Erdos-Ko-Rado, L-intersecting families, Erdos matching).", "motivation": "Hypergraph Turan problems are notoriously difficult. Connecting them to extremal set theory — where more tools exist — provides a new avenue for obtaining upper bounds on Turan densities.", "method": "Construction of families of uniform hypergraphs whose Turan density upper bounds reduce to Erdos-Ko-Rado, L-intersection, or Erdos matching problems via combinatorial reductions.", "result": "Natural hypergraph families for which Turan density bounds follow directly from classical extremal set theory results. Systematic framework for such reductions.", "conclusion": "Extremal set theory is a powerful tool for hypergraph Turan problems; many open Turan density questions may admit reformulation in this language.", "future_work": "Apply the framework to specific hypergraphs of interest (e.g., Fano plane, expanded triangles); develop new extremal set theory results motivated by Turan applications."},
    "2606.02160": {"tldr": "Determines the sharp minimum-degree threshold for pancyclicity in graphs perturbed by a random F-factor, resolving a conjecture of Espuny Diaz and Girao (2023).", "motivation": "Randomly perturbed graphs combine deterministic minimum degree conditions with random edge sprinkling. The Hamiltonicity threshold for perturbed K_r-factors was conjectured but the stronger pancyclic statement was open.", "method": "Introduction of two new parameters tau_{pc}(F) and alpha*_{pan}(F); absorption method combined with probabilistic arguments; structural analysis of F-factors.", "result": "Sharp minimum-degree threshold for pancyclicity in graphs perturbed by a random K_r-factor. General bounds for arbitrary connected F in terms of the new parameters tau_{pc} and alpha*_{pan}.", "conclusion": "Pancyclicity thresholds for perturbed graphs are governed by two natural structural parameters; the Espuny Diaz-Girao conjecture is resolved in a stronger form.", "future_work": "Determine tau_{pc}(F) and alpha*_{pan}(F) exactly for larger classes of F; extension to hypergraphs and other spanning structures."},
    "2606.02210": {"tldr": "Confirms the Balogh-Clemen-Lidicky conjecture that the balanced bipartite construction uniquely maximizes the l2-norm Turan density for K_5^3, and determines the exact maximum number of cliques in K_5^3-free 3-graphs.", "motivation": "The l2-norm Turan problem for hypergraphs generalizes classical Turan problems. The K_5^3 case was asymptotically solved but uniqueness of the extremal construction was conjectured.", "method": "Vertex-colored Turan theorems on graphs as the main ingredient; reduction of hypergraph extremal problems to colored graph extremal problems; stability and exact optimization arguments.", "result": "The balanced bipartite construction is the unique extremal 3-graph for the l2-norm K_5^3 Turan problem for all sufficiently large n. Exact maximum number of cliques in K_5^3-free 3-graphs determined, verifying the Frankl-Gryaznov-Talebanfard conjecture for this case.", "conclusion": "Vertex-colored graph Turan theory provides a powerful reduction for hypergraph extremal problems. The K_5^3 case is now completely resolved.", "future_work": "Apply vertex-colored Turan methods to other hypergraph Turan problems; extend to K_t^r for larger t, r."},
    "2606.02279": {"tldr": "Establishes a sharp dichotomy for counting Hamiltonian paths between prescribed vertices in F-free traceable graphs.", "motivation": "Given an F-free graph with a Hamiltonian path between two vertices, how many such paths must exist? This connects forbidden induced subgraph theory with Hamiltonian path enumeration.", "method": "Structural characterization of F-free graphs with few Hamiltonian paths; construction of infinite families for the negative case; counting arguments for the positive case.", "result": "If F is not an induced subgraph of P_3 + sP_1, there exists an infinite family of F-free graphs with exactly one Hamiltonian path between prescribed vertices. Otherwise, the number of such paths grows with the order of the graph.", "conclusion": "A sharp dichotomy: the class of obstructions is exactly those graphs that are induced subgraphs of P_3 + sP_1. This characterizes when F-free graphs force many Hamiltonian paths.", "future_work": "Quantitative lower bounds on the number of Hamiltonian paths in the positive case; extension to other spanning structures."},
    "2606.02356": {"tldr": "Determines the exact extremal number for 2-connected graphs without cycles of length 1 mod 3, making progress on a 1976 problem of Burr and Erdos.", "motivation": "Burr and Erdos (1976) conjectured that graphs avoiding cycles of length l mod k have linearly many edges. Bollobas proved the conjecture; Erdos asked for the exact extremal number, which remains open for most parameters.", "method": "Structural analysis of 2-connected graphs without cycles of length 1 mod 3; characterization of extremal constructions; degree-based arguments.", "result": "Exact extremal number determined for 2-connected graphs with no cycles of length 1 mod 3. Extends the known cases beyond k <= 4.", "conclusion": "The Burr-Erdos problem is gradually being resolved case by case. The 2-connected case for cycles 1 mod 3 reveals a clean extremal structure.", "future_work": "Extension to general (not necessarily 2-connected) graphs; other residues modulo 3."},
    "2606.02389": {"tldr": "Proves a strong form of Schelp's degree version of the Burr-Erdos conjecture on Ramsey numbers of trees.", "motivation": "The Burr-Erdos conjecture (Ramsey number of any n-vertex tree <= 2n-2) was proved by Zhao. Schelp asked for a degree version: what minimum degree in the host graph forces a monochromatic copy of every bounded-degree tree?", "method": "Szemeredi regularity lemma; embedding techniques for trees in dense graphs; absorption-style arguments for assembling tree embeddings from regular partitions.", "result": "For any eps>0 and Delta, if G has N >= (2+eps)n vertices and min degree >= floor(3N/4), then every 2-coloring of G contains a monochromatic copy of every n-vertex tree with max degree <= Delta. Proves Schelp's conjecture in a strong form.", "conclusion": "The degree version of Burr-Erdos holds with the same asymptotics: trees are Ramsey-unavoidable in dense host graphs.", "future_work": "Sharpen the (2+eps) to 2; remove the bounded-degree condition; multicolor extensions."},
    "2606.02541": {"tldr": "Proves that 3-color van der Waerden numbers grow super-exponentially: w(k;3) > 2^{k log* k / 4} for large k.", "motivation": "Van der Waerden numbers w(k;r) are among the most fundamental quantities in Ramsey theory. While exponential lower bounds exist, whether they can be super-exponential for r=3 was a major open problem.", "method": "Probabilistic construction with a novel recursive coloring scheme; density Hales-Jewett theorem; bootstrapping argument using the structure of arithmetic progressions.", "result": "w(k;3) > 2^{k log* k / 4} for sufficiently large k. Resolves an Erdos-Graham problem on canonical van der Waerden numbers as a corollary.", "conclusion": "Three-color van der Waerden numbers are super-exponential, a landmark result by Fox and Hunter. The log* factor suggests even faster growth may be possible.", "future_work": "Improving the log* factor to a power of log k; extending to r >= 4 colors; tightening the connection to canonical van der Waerden numbers."},
    "2307.02816": {"tldr": "Proves a qualitative strengthening of the Grid-Minor Theorem of Robertson and Seymour, with treedepth as the optimal parameter.", "motivation": "The Grid-Minor Theorem states that graphs excluding a planar minor have treewidth bounded by a function of the grid minor size. The optimal structural parameter for such a result was not known.", "method": "Graph minor theory; treewidth-treedepth duality; construction of product structure representations for graphs excluding a fixed planar minor.", "result": "For every planar graph X of treedepth h, X-minor-free graphs can be represented as subgraphs of H \\boxtimes K_c where H has treewidth at most f(h). Treedepth is proved to be the optimal parameter.", "conclusion": "A fundamental refinement of the Grid-Minor Theorem: treedepth, not treewidth or pathwidth, is the right parameter for planar excluded minors.", "future_work": "Quantitative improvements on f(h); applications to weak coloring numbers and other graph parameters."},
    "2503.15046": {"tldr": "Refines the enumeration of Eulerian orientations of 4-valent planar maps by three parameters, connecting to the six-vertex model of statistical mechanics.", "motivation": "Eulerian orientations of planar maps are a central object in combinatorics and statistical physics (six-vertex model). A refined enumeration by vertex and face types provides deeper structural information.", "method": "Bijection of Ambjorn and Budd relating Eulerian orientations to partial orientations of general maps; generating function techniques; kernel method for functional equations.", "result": "Enumeration of Eulerian orientations of 4-valent planar maps by number of vertices, alternating vertices, and clockwise faces. Refinement of the Kostov / Zinn-Justin-Elvey Price six-vertex model solution.", "conclusion": "The refined enumeration reveals new combinatorial structure in the six-vertex model, connecting alternating vertices with face orientations.", "future_work": "Asymptotic analysis of the refined generating functions; connection to the phase diagram of the six-vertex model."},
    "2505.23293": {"tldr": "Endows mediangle graphs (common generalization of median graphs and Coxeter graphs) with the structure of a contractible cell complex whose cells are products of simplices and oriented matroids.", "motivation": "Median graphs (1-skeleta of CAT(0) cube complexes) and Coxeter graphs share structural properties. A unified geometric framework was sought for geometric group theory applications.", "method": "Cell complex construction on mediangle graphs; simplicial oriented matroid theory; combinatorial convexity arguments for contractibility.", "result": "Mediangle graphs admit a contractible cell complex structure. Cells are products of simplices and simplicial oriented matroids. Bipartite mediangle graphs are characterized as tope graphs of finitary Complexes of Oriented Matroids.", "conclusion": "Mediangle graphs unify the geometry of median graphs and Coxeter graphs in a single cell complex framework with applications to geometric group theory.", "future_work": "Cubical-like structure for non-bipartite mediangle graphs; algorithmic applications to word processing in Coxeter groups."},
    "2510.02776": {"tldr": "Studies spectral extremal problems for the (p,Q)-spectral radius of hypergraphs, connecting spectral radius maximization with classical Turan-type density problems.", "motivation": "Spectral hypergraph theory extends classical spectral graph theory to uniform hypergraphs via tensors. The (p,Q)-spectral radius generalizes several existing spectral parameters.", "method": "Variational characterization of the (p,Q)-spectral radius; relationship with the Lagrangian of hypergraphs; application of hypergraph Turan density results.", "result": "Bounds on the (p,Q)-spectral radius in terms of the Lagrangian and Turan density of Q. Characterization of extremal hypergraphs for several families.", "conclusion": "The (p,Q)-spectral radius provides a unifying framework connecting spectral and extremal hypergraph theory.", "future_work": "Determining exact spectral extremal values for specific hypergraphs; extension to non-uniform hypergraphs."},
    "2511.07712": {"tldr": "Proves a conjectured spectral upper bound on the chromatic number of a graph involving the least adjacency eigenvalue, resolving a conjecture of Fan, Yu and Wang (2012).", "motivation": "Spectral bounds on the chromatic number connect linear algebra with graph coloring. The Fan-Yu-Wang conjecture proposed a specific bound involving lambda_n (the least eigenvalue), which had resisted proof for over a decade.", "method": "Eigenvalue interlacing techniques; analysis of the inertia of adjacency matrices; characterization of equality cases through spectral and structural arguments.", "result": "chi <= (n/2+1+lambda_n) + sqrt((n/2+1+lambda_n)^2 - 4(lambda_n+1)(lambda_n+n/2)) for 3 <= chi <= n-1, with equality precisely for balanced complete split graphs.", "conclusion": "The Fan-Yu-Wang conjecture is true. The bound is sharp and the equality case reveals that balanced complete split graphs are the unique spectral extremal graphs.", "future_work": "Refinements using other eigenvalues; similar bounds for other graph parameters (clique number, independence number)."},
    "2604.03567": {"tldr": "Studies which graphs can be realized as token sliding/jumping reconfiguration graphs of cliques, characterizing feasibility sets for several graph families.", "motivation": "Reconfiguration graphs model the connectivity of solution spaces. Understanding which graphs arise as reconfiguration graphs of cliques reveals the expressive power of the token sliding/jumping model.", "method": "Graph-theoretic characterization of feasibility sets K^{TS}(G) and K^{TJ}(G); construction and non-existence proofs for various target graphs G.", "result": "Characterization of feasibility sets for several families; examples of graphs that are (and are not) realizable as reconfiguration graphs of cliques.", "conclusion": "The realizability problem for reconfiguration graphs of cliques has rich structure, with sharp boundaries between realizable and non-realizable cases.", "future_work": "Complete characterization of realizable graphs; complexity of the recognition problem."},
    "2605.24349": {"tldr": "Establishes a sharp threshold for the limits of Schur multipliers in Polya conversion problems for the q-permanent.", "motivation": "Polya conversion problems ask whether the permanent can be converted to the determinant via linear transformations. The q-permanent interpolates between determinant and permanent, making it a natural setting to study conversion thresholds.", "method": "Algebraic geometry of q-permanent functions; Schur multiplier analysis; classification of preservers via additive matrix spaces. Sharp threshold at n=3 and q != +/-1.", "result": "For n >= 3 and q != +/-1, the q-permanent is not linearly convertible to the determinant or permanent. For n=2, the space of Schur multiplier preservers is completely classified as a (2n-2)-dimensional space of additive matrices.", "conclusion": "The q-permanent exhibits a sharp threshold at n=3: low-dimensional flexibility gives way to combinatorial rigidity. The Schur multiplier approach provides a systematic framework.", "future_work": "Extension to other matrix functions (immanants, Hafnians); connection to geometric complexity theory."},
    "2605.29553": {"tldr": "Determines the sharp threshold for Hamilton cycles in randomly perturbed sparse graphs, improving the leading constant from 6 to the optimal value of 1.", "motivation": "Randomly perturbed graphs model the addition of random noise to a deterministic graph. The threshold for Hamiltonicity in this model was recently studied by Hahn-Klimroth et al., who obtained a suboptimal constant factor of 6.", "method": "Absorption method adapted to the randomly perturbed setting; careful analysis of the sprinkling probability in sparse graphs; optimization of the connection-absorption tradeoff.", "result": "If p >= (1+eps) log(1/alpha)/n and delta(G_alpha) >= alpha n, then G_alpha \\cup G(n,p) is Hamiltonian a.a.s. The bound on p is best possible when alpha = o(1).", "conclusion": "The sharp Hamiltonicity threshold for perturbed sparse graphs is determined. The leading constant 1 is optimal, resolving the constant-factor gap from previous work.", "future_work": "Extension to pancyclicity in the same sparse regime; similar sharp thresholds for other spanning structures (F-factors, powers of Hamilton cycles)."},
    "1708.08723": {"tldr": "Studies outer k-planar and outer k-quasi-planar graphs, bounding their degeneracy and chromatic number, and characterizing edge density.", "motivation": "Beyond-planar graph classes generalize planar graphs by allowing limited edge crossings. Outer k-planar graphs (convex drawings with <= k crossings per edge) are a natural subclass.", "method": "Combinatorial analysis of crossing patterns in convex drawings; degeneracy bounds via edge-counting arguments; construction of extremal examples.", "result": "Outer k-planar graphs are floor(3.5 sqrt(k))-degenerate, hence can be colored with floor(3.5 sqrt(k)) + 1 colors. Tight bounds on edge density for outer k-planar and outer k-quasi-planar graphs.", "conclusion": "The degeneracy of outer k-planar graphs grows sublinearly (O(sqrt(k))), contrasting with general k-planar graphs. Convex position provides strong structural control.", "future_work": "Lower bounds on degeneracy; extension to outer k-gap-planar and other beyond-planar classes; recognition algorithms."},
    "2208.13855": {"tldr": "Studies the rigidity of point configurations when only a subset of pairwise distances is known, proving that dense enough distance graphs contain large globally rigid subgraphs.", "motivation": "Distance geometry asks: given some pairwise distances between n points, when is the configuration determined up to isometry? This has applications in sensor networks and molecular geometry.", "method": "Graph-theoretic rigidity theory; extremal graph theory result: if a distance graph has Omega(n^{3/2}) edges, it contains an induced globally rigid subgraph on Omega(|E|/n) vertices.", "result": "On the line: Omega(n^{3/2}) revealed distances suffice to determine a subset of Omega(n^{1/2}) point locations. The graph-theoretic lemma is a general extremal result about induced globally rigid subgraphs.", "conclusion": "Global rigidity emerges from sufficiently dense distance graphs, even without general position assumptions. The n^{3/2} threshold is extremal.", "future_work": "Tighter bounds on the size of the globally rigid subgraph; extension to higher dimensions and other rigidity models."},
    "2606.02464": {"tldr": "Shows that a gated admission policy for unobservable queues stochastically dominates random routing at equal throughput, with unbounded welfare gains.", "motivation": "Admission control to unobservable queues is a fundamental problem in queueing theory. A controller that remembers past decisions (gated admission) might outperform memoryless controllers (random routing).", "method": "Stochastic ordering techniques; analysis of M/M/1 queue with gated admission policy; definition of Price of Forgetting as the welfare ratio between random routing and optimal gated admission.", "result": "Gated admission stochastically dominates random routing at equal throughput. Welfare-maximizing threshold characterized. Price of Forgetting is unbounded even though absolute welfare gain stays bounded.", "conclusion": "Memory is extremely valuable in admission control: the relative welfare gain can be arbitrarily large, justifying the use of stateful policies.", "future_work": "Extension to multi-server queues and queueing networks; other memory-based policies beyond gated admission."},
    "2312.07726": {"tldr": "Proves a sharp lower bound on the variance of hitting times for simple random walks on graphs: Var(tau_y) >= c E(tau_y)^2 / log n.", "motivation": "Hitting times are fundamental in random walk theory. While expected hitting times are well understood, variance bounds are much harder and were largely open for general graphs.", "method": "Spectral decomposition of the Green's function; relationship between hitting time variance and effective resistance; optimization over the spectrum.", "result": "For any n-vertex graph, Var_x(tau_y) >= c E_x(tau_y)^2 / log n. For trees, n can be replaced by the graph distance between x and y. The bound is sharp up to the log factor.", "conclusion": "Hitting times on graphs cannot be too concentrated: the standard deviation is at least E / sqrt(log n). Trees allow a stronger bound in terms of distance.", "future_work": "Remove the log n factor for general graphs; characterize graphs achieving minimal hitting time variance."},
    "2602.11051": {"tldr": "Proves that positive vertex isoperimetry forces linear expected range for simple random walk, without any bounded-degree assumption.", "motivation": "The range R_t of a random walk (number of distinct vertices visited by time t) is a fundamental parameter. For expander-like graphs, the range should grow linearly, but bounded-degree assumptions are typically required.", "method": "Vertex expansion implies an unweighted Dirichlet inequality, which yields a uniform bound on return probabilities; this in turn forces linear expected range via a direct argument.", "result": "If iota_V(G) = inf |partial_V S|/|S| > 0 (positive vertex expansion), then E_x R_t >= c(G)(t+1) for all x, t. No bounded-degree assumption needed; c(G) depends only on the expansion constant.", "conclusion": "Vertex isoperimetry alone forces linear range growth. The proof is elementary, avoiding spectral or heat-kernel machinery.", "future_work": "Optimal dependence of c(G) on iota_V(G); extension to edge isoperimetry and non-simple random walks."},
    "2603.06886": {"tldr": "Proves that in a random round-robin tournament with equally strong players, the largest scores are all distinct with high probability under mild conditions.", "motivation": "Score distinctness in tournaments is important for ranking and tie-breaking. For equally strong players, when do the top k scores become distinct? This connects to order statistics of correlated random variables.", "method": "Probabilistic analysis of tournament score vectors; anti-concentration inequalities for sums of dependent Bernoulli-like variables; threshold analysis for score separation.", "result": "If k(n) -> infinity and k(n)^2 log(n/k(n)) / sqrt(n) -> 0, then the largest k(n) scores are all distinct w.h.p. In particular, this holds for k(n) = o((n/log n)^{1/4}).", "conclusion": "The largest scores in a random tournament separate naturally up to roughly n^{1/4}. Beyond that, ties become likely.", "future_work": "Sharp threshold for the maximum k with all distinct top scores; extensions to non-uniform tournament models."},
}
